SELECT 
FROM exam e


    e.deleted = 0


        AND e.dept_id = #{deptId}


        AND e.module_id = #{moduleId}


        AND e.exam_name LIKE CONCAT('%', #{examName}, '%')


        AND e.status = #{status}


        AND e.exam_mode = #{examMode}



        AND e.exam_type = #{examType}


ORDER BY e.create_time DESC

SELECT 
FROM exam e


    e.deleted = 0
    AND e.status = 'PUBLISHED'
    AND EXISTS (
        SELECT 1 FROM exam_participant p
        WHERE p.exam_id = e.id AND p.user_id = #{userId}
    )

        AND e.exam_mode = #{examMode}


ORDER BY e.create_time DESC

