UPDATE exam
exam_name = #{examName}, description = #{description}, module_id = #{moduleId}, bank_id = #{bankId}, question_count = #{questionCount}, single_count = #{singleCount}, multi_count = #{multiCount}, judge_count = #{judgeCount}, single_score = #{singleScore}, multi_score = #{multiScore}, judge_score = #{judgeScore}, subject_count = #{subjectCount}, subject_content = #{subjectContent}, subject_attachment = #{subjectAttachment}, position_id = #{positionId}, status = #{status}, start_time = #{startTime}, end_time = #{endTime}, duration = #{duration}, pass_line = #{passLine}, difficulty = #{difficulty}, content_bias = #{contentBias}, published_at = #{publishedAt}, publisher_id = #{publisherId}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
